import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, useScroll, useTransform, useSpring, useMotionValue } from 'framer-motion';
import { Play, ArrowUpRight, Instagram, Mail, ChevronRight, Zap, Briefcase, Award, Sparkles, Send, Check, Loader2, Bot, Github } from 'lucide-react';
import './App.css'; // This links your CSS file

// --- 1. NEW: SOCIAL 3D LOOP COMPONENT ---
const Social3DLoop = () => {
  const [showInsta, setShowInsta] = useState(true);

  useEffect(() => {
    // Loop every 3.5 seconds for a smooth read time
    const timer = setInterval(() => {
      setShowInsta((prev) => !prev);
    }, 3500);
    return () => clearInterval(timer);
  }, []);

  const variants = {
    initial: { 
      opacity: 0, 
      scale: 0.6, 
      z: -100, 
      x: -40, 
      rotateY: -45 
    },
    animate: { 
      opacity: 1, 
      scale: 1.8,
      z: 0, 
      x: 0, 
      rotateY: -20,
      transition: { duration: 1.2, ease: [0.16, 1, 0.3, 1] }
    },
    exit: { 
      opacity: 0, 
      scale: 2.2,
      x: 100,
      rotateY: -10,
      transition: { duration: 0.8, ease: "easeIn" }
    }
  };

  return (
    // Positioned Absolute on the Right Side of the Hero Container with proper 3D perspective setup
    <div className="absolute right-0 top-[20%] md:top-[15%] w-[150px] h-[150px] md:w-[200px] md:h-[200px] flex items-center justify-center pointer-events-none z-30 hidden lg:flex"
      style={{ perspective: "1000px" }}
    >
      <AnimatePresence mode="wait">
        {showInsta ? (
          <motion.a
            key="instagram"
            href="https://instagram.com/aura.edit_ae"
            target="_blank"
            rel="noopener noreferrer"
            className="cursor-pointer pointer-events-auto drop-shadow-2xl flex items-center justify-center"
            variants={variants}
            initial="initial"
            animate="animate"
            exit="exit"
            whileHover={{ scale: 2.0, rotateY: -10, transition: { duration: 0.3 } }}
            style={{ transformStyle: "preserve-3d" }}
          >
            <svg width="64" height="64" viewBox="0 0 24 24" fill="black" xmlns="http://www.w3.org/2000/svg">
              <path d="M7.8,2H16.2C19.4,2 22,4.6 22,7.8V16.2A5.8,5.8 0 0,1 16.2,22H7.8C4.6,22 2,19.4 2,16.2V7.8A5.8,5.8 0 0,1 7.8,2M7.6,4A3.6,3.6 0 0,0 4,7.6V16.4C4,18.39 5.61,20 7.6,20H16.4A3.6,3.6 0 0,0 20,16.4V7.6C20,5.61 18.39,4 16.4,4H7.6M12,6.8A5.2,5.2 0 0,1 17.2,12A5.2,5.2 0 0,1 12,17.2A5.2,5.2 0 0,1 6.8,12A5.2,5.2 0 0,1 12,6.8M12,8.8A3.2,3.2 0 0,0 8.8,12A3.2,3.2 0 0,0 12,15.2A3.2,3.2 0 0,0 15.2,12A3.2,3.2 0 0,0 12,8.8M18,5A1.5,1.5 0 1,1 16.5,6.5A1.5,1.5 0 0,1 18,5Z" />
            </svg>
          </motion.a>
        ) : (
          <motion.a
            key="youtube"
            href="https://youtube.com/@aura.edit_ae"
            target="_blank"
            rel="noopener noreferrer"
            className="cursor-pointer pointer-events-auto drop-shadow-2xl flex items-center justify-center"
            variants={variants}
            initial="initial"
            animate="animate"
            exit="exit"
            whileHover={{ scale: 2.0, rotateY: -10, transition: { duration: 0.3 } }}
            style={{ transformStyle: "preserve-3d" }}
          >
            <svg width="64" height="64" viewBox="0 0 24 24" fill="black" xmlns="http://www.w3.org/2000/svg">
              <path d="M10,15L15.19,12L10,9V15M21.56,7.17C21.69,7.64 21.78,8.27 21.84,9.07C21.91,9.87 21.94,10.56 21.94,11.16L22,12C22,14.19 21.84,15.8 21.56,16.83C21.31,17.73 20.73,18.31 19.83,18.56C19.36,18.69 18.5,18.78 17.18,18.84C15.88,18.91 14.69,18.94 13.59,18.94L12,19C7.81,19 5.2,18.84 4.17,18.56C3.27,18.31 2.69,17.73 2.44,16.83C2.31,16.36 2.22,15.73 2.16,14.93C2.09,14.13 2.06,13.44 2.06,12.84L2,12C2,9.81 2.16,8.2 2.44,7.17C2.69,6.27 3.27,5.69 4.17,5.44C4.64,5.31 5.5,5.22 6.82,5.16C8.12,5.09 9.31,5.06 10.41,5.06L12,5C16.19,5 17.8,5.16 18.83,5.44C19.73,5.69 20.31,6.27 20.56,7.17Z" />
            </svg>
          </motion.a>
        )}
      </AnimatePresence>
    </div>
  );
};

// --- 2. NEW: GAME STYLE MARQUEE COMPONENT ---
const GameMarquee = () => {
  return (
    <div className="game-marquee-wrapper">
      <div className="game-marquee-track">
        {/* Repeating text for smooth loop */}
        <span className="game-text">Build Different</span>
        <span className="game-text">Build Different</span>
        <span className="game-text">Build Different</span>
        <span className="game-text">Build Different</span>
        <span className="game-text">Build Different</span>
        <span className="game-text">Build Different</span>
      </div>
    </div>
  );
};

// --- 3. NEW COMPONENT: PREMIUM APPLE-STYLE PILL ---
const ApplePill = () => {
  const messages = [
    "Crafted in 4K",
    "Focuse Speed , im Speed!",
    "Built with Aura"
  ];
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % messages.length);
    }, 3000); // Transitions every 3 seconds
    return () => clearInterval(timer);
  }, []);

  return (
    // Layout container: Aligns with the logo (start on desktop, center on mobile if needed)
    <div className="flex justify-start w-full mb-8">
      
      {/* The Pill Itself: Minimal, Luxury, Soft Grey Glass */}
      <div className="relative flex items-center justify-center px-6 h-[42px] md:h-[46px] bg-gray-80/80 backdrop-blur-md border border-black/5 rounded-full shadow-[0_2px_10px_rgba(0,0,0,0.03)] overflow-hidden">
        
        {/* Subtle inner shine */}
        <div className="absolute inset-0 bg-gradient-to-tr from-white/60 to-transparent pointer-events-none" />

        {/* Animated Text */}
        <AnimatePresence mode="wait">
          <motion.span
            key={index}
            initial={{ y: 15, opacity: 0, filter: 'blur(3px)' }}
            animate={{ y: 0, opacity: 1, filter: 'blur(0px)' }}
            exit={{ y: -15, opacity: 0, filter: 'blur(3px)' }}
            transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }} // The "Apple" Bezier Curve
            className="text-[13px] md:text-[14px] font-medium text-black/70 tracking-wide whitespace-nowrap"
          >
            {messages[index]}
          </motion.span>
        </AnimatePresence>
      
      </div>
    </div>
  );
};

// --- CONFETTI SPARK EFFECT ---

const AntigravitySpark = ({ delay = 0, duration = 6, colorIndex = 0, onComplete }) => {
  const randomX = Math.random() * 100;
  const randomRotation = Math.random() * 360;
  const randomScale = Math.random() * 1 + 1;
  const randomDuration = duration + Math.random() * 6; // Increased from 3 to 6

  // Color palette: Red, Pink, Blue
  const colors = [
    { gradient: 'from-red-400 via-red-200 to-red-100', glow: 'rgba(248, 113, 113, 0.75)' }, // Red
    { gradient: 'from-pink-400 via-pink-200 to-pink-100', glow: 'rgba(244, 114, 182, 0.75)' }, // Pink
    { gradient: 'from-blue-400 via-blue-200 to-blue-100', glow: 'rgba(96, 165, 250, 0.75)' }, // Blue
  ];

  const color = colors[colorIndex % 3];

  return (
    <motion.div
      initial={{ 
        x: `${randomX}vw`, 
        y: "100vh", 
        rotate: randomRotation,
        opacity: 0.75,
        scale: randomScale 
      }}
      animate={{ 
        y: "-10vh",
        x: `${randomX + (Math.random() - 0.5) * 10}vw`,
        rotate: randomRotation + 720,
        opacity: [0.75, 0.75, 0.75, 0] // Stay visible longer
      }}
      transition={{ 
        duration: randomDuration, 
        delay: delay, 
        ease: "easeOut"
      }}
      onAnimationComplete={onComplete}
      className="fixed pointer-events-none"
      style={{ willChange: 'transform' }}
    >
      <div className={`w-2 h-2 bg-gradient-to-br ${color.gradient} rounded-full shadow-lg`}
        style={{
          boxShadow: `0 0 12px ${color.glow}, 0 0 24px ${color.glow.replace('0.75', '0.4')}, 0 0 36px ${color.glow.replace('0.75', '0.2')}`
        }}
      />
    </motion.div>
  );
};

const ConfettiSparks = React.memo(() => {
  const [sparks, setSparks] = useState([]);
  const colorIndexRef = useRef(0);

  useEffect(() => {
    // Generate initial sparks (reduced for better performance)
    const initialSparks = Array.from({ length: 25 }, (_, i) => ({
      id: i,
      delay: i * 0.04,
      colorIndex: i % 3,
    }));
    setSparks(initialSparks);
    colorIndexRef.current = 25;

    // Create new sparks continuously (optimal speed for visual effect)
    const interval = setInterval(() => {
      setSparks(prev => [
        ...prev.slice(-25), // Keep only last 25 sparks
        {
          id: Date.now() + Math.random(),
          delay: 0,
          colorIndex: (colorIndexRef.current++) % 3,
        }
      ]);
    }, 800); // Optimized spawn interval

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
      {sparks.map(spark => (
        <AntigravitySpark 
          key={spark.id} 
          delay={spark.delay} 
          duration={12}
          colorIndex={spark.colorIndex}
        />
      ))}
    </div>
  );
});

ConfettiSparks.displayName = "ConfettiSparks";

// --- COMPONENTS ---

const AuraLogo = React.memo(({ className = "w-8 h-8" }) => (
  <svg viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <motion.path 
      d="M50 5 L95 80 L5 80 Z" 
      stroke="#000000" 
      strokeWidth="4" 
      strokeLinecap="round" 
      strokeLinejoin="round"
      initial={{ pathLength: 0 }}
      animate={{ pathLength: 1 }}
      transition={{ duration: 2, ease: "easeInOut" }}
    />
    <motion.path 
      d="M50 30 L75 70 L25 70 Z" 
      fill="#000000"
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 0.1, scale: 1 }}
      transition={{ delay: 1, duration: 1 }}
    />
  </svg>
));

const CustomCursor = React.memo(() => {
  const cursorX = useMotionValue(-100);
  const cursorY = useMotionValue(-100);
  const ringX = useMotionValue(-100);
  const ringY = useMotionValue(-100);

  const springConfig = { damping: 25, stiffness: 700, mass: 0.1 };
  const ringSpringConfig = { damping: 30, stiffness: 200, mass: 0.5 };

  const cursorXSpring = useSpring(cursorX, springConfig);
  const cursorYSpring = useSpring(cursorY, springConfig);
  const ringXSpring = useSpring(ringX, ringSpringConfig);
  const ringYSpring = useSpring(ringY, ringSpringConfig);

  const [isHovering, setIsHovering] = useState(false);

  useEffect(() => {
    const moveCursor = (e) => {
      cursorX.set(e.clientX - 4);
      cursorY.set(e.clientY - 4);
      ringX.set(e.clientX - 16);
      ringY.set(e.clientY - 16);
    };

    const handleMouseOver = (e) => {
      if (e.target.closest('a, button, input, textarea, .interactive')) {
        setIsHovering(true);
      } else {
        setIsHovering(false);
      }
    };

    window.addEventListener('mousemove', moveCursor);
    window.addEventListener('mouseover', handleMouseOver);

    return () => {
      window.removeEventListener('mousemove', moveCursor);
      window.removeEventListener('mouseover', handleMouseOver);
    };
  }, [cursorX, cursorY, ringX, ringY]);

  return (
    <>
      <motion.div
        className="custom-cursor fixed top-0 left-0 w-2 h-2 bg-black rounded-full pointer-events-none z-[100]"
        style={{ x: cursorXSpring, y: cursorYSpring, scale: isHovering ? 0 : 1 }}
      />
      <motion.div
        className="custom-cursor fixed top-0 left-0 w-8 h-8 border border-black/30 rounded-full pointer-events-none z-[99]"
        style={{ 
          x: ringXSpring, 
          y: ringYSpring,
          scale: isHovering ? 1.5 : 1,
          backgroundColor: isHovering ? 'rgba(0,0,0,0.05)' : 'transparent',
          borderColor: isHovering ? 'rgba(0,0,0,0)' : 'rgba(0,0,0,0.3)',
        }}
        transition={{ duration: 0.2 }}
      />
    </>
  );
});

const MagneticButton = React.memo(({ children, className, onClick, primary = false }) => {
  const ref = useRef(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const handleMouse = (e) => {
    const { clientX, clientY } = e;
    const { height, width, left, top } = ref.current.getBoundingClientRect();
    const middleX = clientX - (left + width / 2);
    const middleY = clientY - (top + height / 2);
    setPosition({ x: middleX * 0.2, y: middleY * 0.2 });
  };

  const reset = () => setPosition({ x: 0, y: 0 });

  const { x, y } = position;

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouse}
      onMouseLeave={reset}
      animate={{ x, y }}
      transition={{ type: "spring", stiffness: 150, damping: 15, mass: 0.1 }}
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
      className={`relative overflow-hidden rounded-full group interactive transition-shadow duration-300 ${
        primary 
          ? 'bg-black text-white font-semibold shadow-[0_8px_20px_rgba(0,0,0,0.15)] hover:shadow-[0_12px_25px_rgba(0,0,0,0.25)]' 
          : 'bg-white/60 border border-white/40 text-black backdrop-blur-[20px] shadow-[0_10px_30px_rgba(0,0,0,0.05)] hover:shadow-md hover:bg-white/80'
      } ${className}`}
    >
      <span className="relative z-10 flex items-center justify-center gap-2">
        {children}
      </span>
    </motion.button>
  );
});

const TiltCard = React.memo(({ children, className }) => {
  const ref = useRef(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const mouseXSpring = useSpring(x, { stiffness: 300, damping: 30 });
  const mouseYSpring = useSpring(y, { stiffness: 300, damping: 30 });

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

  const handleMouseMove = (e) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const xPct = mouseX / width - 0.5;
    const yPct = mouseY / height - 0.5;
    x.set(xPct);
    y.set(yPct);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ 
        rotateX, 
        rotateY, 
        transformStyle: "preserve-3d",
        boxShadow: "0 20px 50px rgba(0,0,0,0.05), inset 0 0 0 1px rgba(255,255,255,0.5), inset 0 20px 40px rgba(255,255,255,0.6)"
      }}
      className={`relative rounded-[24px] bg-white/30 backdrop-blur-[40px] p-8 transition-colors hover:bg-white/40 interactive ${className}`}
    >
      <div style={{ transform: "translateZ(40px)", transformStyle: "preserve-3d" }} className="w-full h-full">
        {children}
      </div>
      <motion.div 
        className="absolute inset-0 rounded-[24px] pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500"
        style={{
          background: useTransform(
            [mouseXSpring, mouseYSpring],
            ([mx, my]) => `radial-gradient(circle at ${(mx + 0.5) * 100}% ${(my + 0.5) * 100}%, rgba(255, 255, 255, 0.5), transparent 60%)`
          )
        }}
      />
    </motion.div>
  );
});

